@dataclass
class RunRequest:
    """Unified execution request created by both CLI and Web UI."""
    story_dir: Path
    format_id: FormatId
    format_plan: Optional[FormatPlan] = None
    effect_profile: Optional[EffectProfile] = None
    layout_profile: Optional[LayoutProfile] = None
    output_name: str = "Full_Master_Video_26M.mp4"
    options: Dict[str, Any] = field(default_factory=dict)
    fingerprint: str = ""

    def __post_init__(self):
        if self.format_plan is None:
            self.format_plan = create_default_format_plan(self.format_id)
        if self.effect_profile is None:
            self.effect_profile = self.format_plan.effect_profile
        if self.layout_profile is None and self.format_id == FormatId.F4:
            self.layout_profile = self.format_plan.layout_profile
        if not self.fingerprint:
            raw = f"{self.story_dir.name}_{self.format_id.value}_{self.format_plan.fingerprint}"
            self.fingerprint = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]


